"""Gera o relatório autossuficiente usando exclusivamente os resultados salvos."""
from pathlib import Path
import base64
import html
import json
import re
import hashlib

ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / 'notebooks/entregavel_datathon_fgv.ipynb'
TARGET = SOURCE.with_suffix('.html')
raw = SOURCE.read_bytes()
nb = json.loads(raw)

def esc(s): return html.escape(str(s))
def join(v): return ''.join(v) if isinstance(v, list) else v

def outputs(index, tables=True, images=True, streams=False):
    parts = []
    for j, out in enumerate(nb['cells'][index].get('outputs', [])):
        data = out.get('data', {})
        if 'image/png' in data and images:
            parts.append(f'<figure><a href="#" class="zoom" aria-label="Ampliar gráfico da célula {index + 1}"><img loading="lazy" src="data:image/png;base64,{join(data["image/png"])}" alt="{esc(CAPTIONS.get(index, "Visualização do notebook"))}"></a><figcaption>{esc(CAPTIONS.get(index, "Visualização original"))} <span>↗ Clique para ampliar</span></figcaption></figure>')
        elif 'text/html' in data and tables:
            table = re.sub(r'<style\b[^>]*>.*?</style>', '', join(data['text/html']), flags=re.S)
            parts.append('<div class="table-scroll" tabindex="0" role="region" aria-label="Tabela de resultados">' + table + '</div>')
        elif streams and out.get('output_type') == 'stream':
            parts.append('<pre class="output">' + esc(join(out.get('text', ''))) + '</pre>')
    return ''.join(parts)

def code(*indices):
    return '<details class="code"><summary>Consultar código e reprodução</summary>' + ''.join(f'<p class="cell-label">Célula {i+1} · Python</p><pre><code>{esc(join(nb["cells"][i]["source"]))}</code></pre>' for i in indices) + '</details>'

def note(title, text): return f'<aside class="note"><strong>{title}</strong><p>{text}</p></aside>'
def section(id, num, title, subtitle, body):
    return f'<section id="{id}" class="chapter"><header class="chapter-head"><span class="chapter-num">{num}</span><div><h2>{title}</h2><p>{subtitle}</p></div></header>{body}</section>'

